DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[PurchaseOrderDetail]([PurchaseOrderID],[PurchaseOrderDetailID],[DueDate],[OrderQty],[ProductID],[UnitPrice],[LineTotal],[ReceivedQty],[RejectedQty],[StockedQty],[ModifiedDate],LoadBatchID) SELECT S.[PurchaseOrderID],S.[PurchaseOrderDetailID],S.[DueDate],S.[OrderQty],S.[ProductID],S.[UnitPrice],S.[LineTotal],S.[ReceivedQty],S.[RejectedQty],S.[StockedQty],S.[ModifiedDate],@B FROM ssis_flow.Delta_PurchaseOrderDetail S;
INSERT stg.[PurchaseOrderDetail]([PurchaseOrderID],[PurchaseOrderDetailID],[DueDate],[OrderQty],[ProductID],[UnitPrice],[LineTotal],[ReceivedQty],[RejectedQty],[StockedQty],[ModifiedDate],LoadBatchID) SELECT [PurchaseOrderID],[PurchaseOrderDetailID],[DueDate],[OrderQty],[ProductID],[UnitPrice],[LineTotal],[ReceivedQty],[RejectedQty],[StockedQty],[ModifiedDate],@B FROM etl_raw.[PurchaseOrderDetail];
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.PurchaseOrderDetail','I',@Next,(SELECT R.[PurchaseOrderID],R.[PurchaseOrderDetailID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[PurchaseOrderDetail] R;
END ELSE BEGIN
SELECT [PurchaseOrderID],[PurchaseOrderDetailID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_PurchaseOrderDetail FROM ssis_flow.Delta_PurchaseOrderDetail;
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.PurchaseOrderDetail',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[PurchaseOrderID],C.[PurchaseOrderDetailID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_PurchaseOrderDetail C LEFT JOIN etl_raw.[PurchaseOrderDetail] R ON R.[PurchaseOrderID]=C.[PurchaseOrderID] AND R.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID];
DELETE R FROM etl_raw.[PurchaseOrderDetail] R JOIN #CT_PurchaseOrderDetail C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] AND R.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[DueDate]=S.[DueDate],R.[OrderQty]=S.[OrderQty],R.[ProductID]=S.[ProductID],R.[UnitPrice]=S.[UnitPrice],R.[LineTotal]=S.[LineTotal],R.[ReceivedQty]=S.[ReceivedQty],R.[RejectedQty]=S.[RejectedQty],R.[StockedQty]=S.[StockedQty],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[PurchaseOrderDetail] R JOIN #CT_PurchaseOrderDetail C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] AND R.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID] JOIN ssis_flow.Delta_PurchaseOrderDetail S ON S.[PurchaseOrderID]=C.[PurchaseOrderID] AND S.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[PurchaseOrderDetail]([PurchaseOrderID],[PurchaseOrderDetailID],[DueDate],[OrderQty],[ProductID],[UnitPrice],[LineTotal],[ReceivedQty],[RejectedQty],[StockedQty],[ModifiedDate],LoadBatchID) SELECT S.[PurchaseOrderID],S.[PurchaseOrderDetailID],S.[DueDate],S.[OrderQty],S.[ProductID],S.[UnitPrice],S.[LineTotal],S.[ReceivedQty],S.[RejectedQty],S.[StockedQty],S.[ModifiedDate],@B FROM #CT_PurchaseOrderDetail C JOIN ssis_flow.Delta_PurchaseOrderDetail S ON S.[PurchaseOrderID]=C.[PurchaseOrderID] AND S.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[PurchaseOrderDetail] R WHERE R.[PurchaseOrderID]=S.[PurchaseOrderID] AND R.[PurchaseOrderDetailID]=S.[PurchaseOrderDetailID]);
INSERT stg.[PurchaseOrderDetail]([PurchaseOrderID],[PurchaseOrderDetailID],[DueDate],[OrderQty],[ProductID],[UnitPrice],[LineTotal],[ReceivedQty],[RejectedQty],[StockedQty],[ModifiedDate],LoadBatchID) SELECT R.[PurchaseOrderID],R.[PurchaseOrderDetailID],R.[DueDate],R.[OrderQty],R.[ProductID],R.[UnitPrice],R.[LineTotal],R.[ReceivedQty],R.[RejectedQty],R.[StockedQty],R.[ModifiedDate],@B FROM etl_raw.[PurchaseOrderDetail] R JOIN #CT_PurchaseOrderDetail C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] AND R.[PurchaseOrderDetailID]=C.[PurchaseOrderDetailID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;